export default function Error({
  error,
  retry,
}: {
  error: Error & { digest?: string }
  retry: () => void
}) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <div className="error-page">
      <h1>An error occurred on client</h1>
      <p>Sorry, something went wrong.</p>
      <button onClick={() => retry()}>Try again</button>
    </div>
  )
}

