interface ApiPost {
  id: number
  title: string
  content: string
  createdAt?: string
  updatedAt?: string
}

interface UpdatePostBody {
  title?: string
  content?: string
}

type Context = {
  params: Promise<{ id: string }>
}

export async function GET(request: Request, { params }: Context) {
  const { id } = await params

  const post: ApiPost = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post)
}

export async function PUT(request: Request, { params }: Context) {
  const { id } = await params
  const { title, content }: UpdatePostBody = await request.json()

  const updatedPost: ApiPost = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost)
}

export async function DELETE(request: Request, { params }: Context) {
  const { id } = await params

  return Response.json({ message: `Post ${id} deleted successfully` })
}

